/* Simulateur de stress : P&L par facteur, comparaison à la VaR */
(function () {
  var svg = document.getElementById("st-chart");
  if (!svg) return;
  var EQ=40, BOND=35, BDUR=6, CRED=20, CSDUR=4, FX=15;   // M€ / durations
  var VAR99=2.0;                                          // VaR 1j 99% (M€), temps calme
  function v(id){ return parseFloat(document.getElementById(id).value); }
  function setT(id,t){ var e=document.getElementById(id); if(e) e.textContent=t; }
  function al(){ return document.body.getAttribute("data-active-lang")||"fr"; }
  function sgn(x){ return (x>=0?"+":"")+x; }

  function draw(){
    var eq=v("st-eq"), rt=v("st-rt"), cs=v("st-cs"), fx=v("st-fx");
    setT("st-eq-o",(eq>=0?"+":"")+eq+"%"); setT("st-rt-o",sgn(rt)+" bps"); setT("st-cs-o",sgn(cs)+" bps"); setT("st-fx-o",(fx>=0?"+":"")+fx+"%");
    var pEq=EQ*eq/100, pRt=-BOND*BDUR*rt/10000, pCs=-CRED*CSDUR*cs/10000, pFx=FX*fx/100;
    var total=pEq+pRt+pCs+pFx;
    setT("st-total", total.toFixed(2)+" M€");
    setT("st-mult", (Math.abs(total)/VAR99).toFixed(1)+"×");

    var labs = al()==="en" ? ["Equities","Rates","Credit","FX","Total"]
             : al()==="nl" ? ["Aandelen","Rente","Krediet","Wissel","Totaal"]
             : ["Actions","Taux","Crédit","Change","Total"];
    var vals=[pEq,pRt,pCs,pFx,total];

    var W=520,H=260,L=16,R=16,T=16,B=40, pw=W-L-R, ph=H-T-B;
    var amax=Math.max(VAR99, Math.abs(total)); for (var i=0;i<vals.length;i++) amax=Math.max(amax,Math.abs(vals[i]));
    amax*=1.15;
    var y0 = T + ph*amax/(2*amax); // = T + ph/2 (zéro au centre)
    function py(val){ return T + (1-(val+amax)/(2*amax))*ph; }
    var n=vals.length, slot=pw/n, bw=slot*0.5;

    var g="";
    // lignes VaR ±
    g+='<line x1="'+L+'" y1="'+py(VAR99).toFixed(1)+'" x2="'+(L+pw)+'" y2="'+py(VAR99).toFixed(1)+'" stroke="var(--gold)" stroke-width="1.3" stroke-dasharray="4 3"/>';
    g+='<line x1="'+L+'" y1="'+py(-VAR99).toFixed(1)+'" x2="'+(L+pw)+'" y2="'+py(-VAR99).toFixed(1)+'" stroke="var(--gold)" stroke-width="1.3" stroke-dasharray="4 3"/>';
    g+='<text class="tick" x="'+(L+pw)+'" y="'+(py(VAR99)-3).toFixed(1)+'" text-anchor="end" fill="var(--gold)">± VaR 99%</text>';
    // barres
    for (var b2=0;b2<n;b2++){
      var cx=L+slot*b2+slot/2, val=vals[b2];
      var yTop=py(Math.max(0,val)), yBot=py(Math.min(0,val));
      var hh=Math.max(1,yBot-yTop);
      var fill = val<0 ? "var(--crimson)" : "var(--teal)";
      var isTot = (b2===n-1);
      g+='<rect x="'+(cx-bw/2).toFixed(1)+'" y="'+yTop.toFixed(1)+'" width="'+bw.toFixed(1)+'" height="'+hh.toFixed(1)+'" rx="2" fill="'+fill+'" opacity="'+(isTot?"0.95":"0.65")+'"'+(isTot?' stroke="var(--ink)" stroke-width="1"':'')+'/>';
      // valeur
      var vy = val<0 ? yBot+13 : yTop-5;
      g+='<text class="tick" x="'+cx.toFixed(1)+'" y="'+vy.toFixed(1)+'" text-anchor="middle" fill="var(--ink-soft)">'+(val>=0?"+":"")+val.toFixed(1)+'</text>';
      // label
      g+='<text class="lab" x="'+cx.toFixed(1)+'" y="'+(H-8)+'" text-anchor="middle">'+labs[b2]+'</text>';
    }
    // ligne zéro
    g+='<line class="axis" x1="'+L+'" y1="'+py(0).toFixed(1)+'" x2="'+(L+pw)+'" y2="'+py(0).toFixed(1)+'"/>';
    svg.innerHTML=g;
  }

  ["st-eq","st-rt","st-cs","st-fx"].forEach(function(id){ var e=document.getElementById(id); if(e) e.addEventListener("input", draw); });
  document.querySelectorAll(".st-presets button").forEach(function(btn){
    btn.addEventListener("click", function(){
      document.getElementById("st-eq").value=btn.getAttribute("data-eq");
      document.getElementById("st-rt").value=btn.getAttribute("data-rt");
      document.getElementById("st-cs").value=btn.getAttribute("data-cs");
      document.getElementById("st-fx").value=btn.getAttribute("data-fx");
      draw();
    });
  });
  document.querySelectorAll("[data-set-lang]").forEach(function(b){ b.addEventListener("click", function(){ setTimeout(draw,10); }); });
  document.addEventListener("DOMContentLoaded", draw);
  draw();
})();
